// Based on the algorithm by Stefan Gustavson

const F2: number = 0.5 * (Math.sqrt(3) - 1);
const G2: number = (3 - Math.sqrt(3)) / 6;
const F3: number = 1 / 3;
const G3: number = 1 / 6;

