      generateChunk(this.seed, cx, cz, blocks);
      const e = this.edits.get(key);
      if (e) {
        for (const [idx, id] of e) {
          blocks[idx] = id;
        }
      }
      chunk = { cx, cz, blocks };
      this.chunks.set(key, chunk);
    }
    return chunk;
  }

  hasChunk(cx: number, cz: number): boolean {
    return this.chunks.has(chunkKey(cx, cz));
