// HUD overlay for performance metrics
export class MetricsHUD {
  private readonly el: HTMLDivElement;
  private fps = 0;
  private frameTimes: number[] = [];
  private drawCalls = 0;
  private chunks = 0;
  private heapMB = 0;

  constructor(containerId: string) {
