args.oldString:
export class MetricsHUD {
  private readonly el: HTMLDivElement;
  private fps = 0;
  private frameTimes: number[] = [];
  private drawCalls = 0;
  private chunks = 0;
  private heapMB = 0;

  constructor(containerId: string) {
    this.el = document.getElementById(containerId)!;
  }

  tick(deltaMs: number): void {
    this.frameTimes.push(deltaMs);
    if (this.frameTimes.length > 60) this.frameTimes.shift();

    this.fps = 1000 / (this.frameTimes.reduce((a, b) => a + b, 0) / this.frameTimes.length);

    if (performance.memory) {
      this.heapMB = Math.round((performance.memory as any).usedJSHeapSize / 1048576);
    }
  }

args.newString:
export class MetricsHUD {
  private readonly el: HTMLElement;
  private fps = 0;
  private frameTimes: number[] = [];
  private drawCalls = 0;
  private chunks = 0;
  private heapMB = 0;

  constructor(containerId: string) {
    this.el = document.getElementById(containerId)!;
  }

  tick(deltaMs: number): void {
    this.frameTimes.push(deltaMs);
    if (this.frameTimes.length > 60) this.frameTimes.shift();

    this.fps = 1000 / (this.frameTimes.reduce((a, b) => a + b, 0) / this.frameTimes.length);

    const mem = (performance as any).memory;
    if (mem) {
      this.heapMB = Math.round(mem.usedJSHeapSize / 1048576);
    }
  }

